+                summary.pricedLegs += 1;
+            }
+        });
+    });
+    if (!any) return null;   // nothing priced (e.g. pre-fa#1460: models empty)
+    summary.usd14d = Math.round(summary.usd14d * 100) / 100;
+    return summary;
+}
