+var DEFAULT_PRICING_FILE = 'data/model-pricing.json';   // the ONE home
+var COST_WINDOW_DAYS = 14;                              // global Σ$ window
+var COST_WINDOW_MS = COST_WINDOW_DAYS * 24 * 60 * 60 * 1000;
