function normalizeTokens(input) {
    var map = {};
    if (Array.isArray(input)) {
        input.forEach(function (r) {
            if (!r) return;
            var key = r.pr != null ? 'pr-' + r.pr
                : (r.issue != null ? 'issue-' + r.issue : null);
            if (!key) return;
            (map[key] = map[key] || []).push(normTokenRow(r));
