    } else if (input && typeof input === 'object') {
        Object.keys(input).forEach(function (k) {
            if (!Array.isArray(input[k])) return;
            map[k] = input[k].map(normTokenRow);
        });
    }
    Object.keys(map).forEach(function (k) {
        map[k].sort(function (a, b) {
